// Shared helpers: data loading, time formatting, user settings, tide math.

export const TZ = "America/Los_Angeles";

const cache = {};
// `name` is a file in data/ (regenerated by the workflow); pass `path` for other committed files.
export async function load(name, path = `data/${name}.json`) {
  if (!cache[name]) {
    cache[name] = fetch(path, { cache: "no-cache" })
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }
  return cache[name];
}

export async function loadAll(names) {
  const vals = await Promise.all(names.map((n) => load(n)));
  return Object.fromEntries(names.map((n, i) => [n, vals[i]]));
}

// ---------- time ----------
const fmtCache = {};
function fmt(opts) {
  const k = JSON.stringify(opts);
  return (fmtCache[k] ||= new Intl.DateTimeFormat("en-US", { timeZone: TZ, ...opts }));
}
export const toDate = (s) => (s instanceof Date ? s : new Date(s));
export const fmtTime = (s) => fmt({ hour: "numeric", minute: "2-digit" }).format(toDate(s));
export const fmtDay = (s) => fmt({ weekday: "short", month: "short", day: "numeric" }).format(toDate(s));
export const fmtDayTime = (s) =>
  fmt({ weekday: "short", hour: "numeric", minute: "2-digit" }).format(toDate(s));
export const localDateKey = (s) => fmt({ year: "numeric", month: "2-digit", day: "2-digit" })
  .format(toDate(s)).replace(/(\d+)\/(\d+)\/(\d+)/, "$3-$1-$2");

export function ago(s) {
  if (!s) return "never";
  const min = Math.round((Date.now() - toDate(s)) / 60000);
  if (min < 1) return "just now";
  if (min < 60) return `${min} min ago`;
  const h = Math.round(min / 60);
  if (h < 48) return `${h} h ago`;
  return `${Math.round(h / 24)} d ago`;
}

export function uplotTz(ts) {
  return uPlot.tzDate(new Date(ts * 1e3), TZ);
}

// ---------- settings ----------
export const DEFAULTS = {
  lowTideFt: 0.0,     // "workable" low tide threshold (ft MLLW)
  heatF: 75,          // air temp at low tide that raises a heat-exposure flag
  rainIn24h: 1.0,     // placeholder — set to your growing area's DOH rule
  gustMph: 20,        // gust that raises a wind flag
  vibrioF: 60,        // water temp in Vibrio season (May–Sept) that raises a flag
  freshenPsu: 1.0,    // daily-mean drop in model salinity at the bay mouth that adds a runoff note
};

export function getSettings() {
  try {
    return { ...DEFAULTS, ...JSON.parse(localStorage.getItem("acantha-settings") || "{}") };
  } catch {
    return { ...DEFAULTS };
  }
}
export function saveSettings(s) {
  try { localStorage.setItem("acantha-settings", JSON.stringify(s)); } catch {}
}

// ---------- tides & sun ----------
export function isDaylight(t, sun) {
  const key = localDateKey(t);
  const d = sun?.days?.find((x) => x.date === key);
  if (!d) return null;
  const ts = toDate(t);
  return ts >= toDate(d.sunrise) && ts <= toDate(d.sunset);
}

// Tide height at time t by cosine interpolation between hi/lo predictions.
export function tideAt(t, hilo) {
  const ms = toDate(t).getTime();
  for (let i = 0; i < hilo.length - 1; i++) {
    const a = toDate(hilo[i].t).getTime(), b = toDate(hilo[i + 1].t).getTime();
    if (ms >= a && ms <= b) {
      const f = (ms - a) / (b - a);
      const v = hilo[i].v + (hilo[i + 1].v - hilo[i].v) * (1 - Math.cos(Math.PI * f)) / 2;
      return { v, rising: hilo[i + 1].v > hilo[i].v, next: hilo[i + 1] };
    }
  }
  return null;
}

export function nearestHour(series, t) {
  const ms = toDate(t).getTime();
  let best = null, bd = Infinity;
  for (const r of series || []) {
    const d = Math.abs(toDate(r.t).getTime() - ms);
    if (d < bd) { bd = d; best = r; }
  }
  return bd <= 90 * 60000 ? best : null;
}

// Latest non-null value for a field across an observation series.
export function latestValue(series, key) {
  for (let i = (series?.length || 0) - 1; i >= 0; i--) {
    if (series[i][key] != null) return { v: series[i][key], t: series[i].t };
  }
  return null;
}

export const compass = (deg) =>
  deg == null ? "" : ["N","NNE","NE","ENE","E","ESE","SE","SSE","S","SSW","SW","WSW","W","WNW","NW","NNW"][
    Math.round(deg / 22.5) % 16];

export const num = (v, d = 0) => (v == null || Number.isNaN(v) ? "—" : Number(v).toFixed(d));

export function el(tag, attrs = {}, ...kids) {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "class") e.className = v;
    else if (k === "html") e.innerHTML = v;
    else if (k.startsWith("on")) e.addEventListener(k.slice(2), v);
    else if (v != null) e.setAttribute(k, v);
  }
  for (const k of kids.flat()) if (k != null) e.append(k.nodeType ? k : document.createTextNode(k));
  return e;
}

// uPlot plugin: shade night-time using sunrise/sunset.
export function nightShade(sun) {
  return {
    hooks: {
      drawClear: (u) => {
        if (!sun?.days) return;
        const { ctx, bbox } = u;
        const style = getComputedStyle(document.documentElement).getPropertyValue("--night").trim();
        ctx.save();
        ctx.fillStyle = style || "rgba(0,0,0,.06)";
        const days = sun.days;
        for (let i = 0; i < days.length - 1; i++) {
          const x0 = u.valToPos(toDate(days[i].sunset) / 1e3, "x", true);
          const x1 = u.valToPos(toDate(days[i + 1].sunrise) / 1e3, "x", true);
          const a = Math.max(x0, bbox.left), b = Math.min(x1, bbox.left + bbox.width);
          if (b > a) ctx.fillRect(a, bbox.top, b - a, bbox.height);
        }
        ctx.restore();
      },
    },
  };
}

export function nowLine() {
  return {
    hooks: {
      draw: (u) => {
        const x = u.valToPos(Date.now() / 1e3, "x", true);
        if (x < u.bbox.left || x > u.bbox.left + u.bbox.width) return;
        const { ctx } = u;
        ctx.save();
        ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue("--accent-2").trim();
        ctx.setLineDash([4, 4]);
        ctx.lineWidth = 1.5 * devicePixelRatio;
        ctx.beginPath();
        ctx.moveTo(x, u.bbox.top);
        ctx.lineTo(x, u.bbox.top + u.bbox.height);
        ctx.stroke();
        ctx.restore();
      },
    },
  };
}

export const cssVar = (n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim();

export function sourceBadge(meta, key) {
  const s = meta?.sources?.[key];
  if (!s) return el("span", { class: "badge muted" }, "no data");
  const stale = s.fetched_at && Date.now() - toDate(s.fetched_at) > 3 * 3600e3;
  const cls = !s.ok ? "badge bad" : stale ? "badge warn" : "badge ok";
  return el("span", { class: cls, title: s.error || "" }, s.ok ? `updated ${ago(s.fetched_at)}` :
    `source error · last good ${ago(s.fetched_at)}`);
}

// ---------- farm sensors ----------
const SENSOR_SERIES = ["--series-1", "--series-2", "--series-3", "--accent-2"];

// uPlot plugin: shade time when a sensor's probe was out of the water.
function exposedShade(xs, exposed) {
  return {
    hooks: {
      drawClear: (u) => {
        const { ctx, bbox } = u;
        ctx.save();
        ctx.fillStyle = cssVar("--accent-2") + "26";
        let start = null;
        for (let i = 0; i <= xs.length; i++) {
          const on = i < xs.length && exposed[i];
          if (on && start == null) start = xs[i];
          if (!on && start != null) {
            const a = Math.max(u.valToPos(start, "x", true), bbox.left);
            const b = Math.min(u.valToPos(xs[i - 1], "x", true), bbox.left + bbox.width);
            if (b > a) ctx.fillRect(a, bbox.top, b - a, bbox.height);
            start = null;
          }
        }
        ctx.restore();
      },
    },
  };
}

// Temperature (°F) chart for one or more farm sensors over the last `hours`.
// Readings that failed QC are dropped; gaps in reporting show as breaks in the line.
// With a single station, time out of the water is shaded.
export function sensorChart(box, stations, { hours = 72, width, height = 160, legend = true, sun } = {}) {
  const since = Date.now() - hours * 3600e3;
  const rows = stations.map((s) => new Map((s.series || [])
    .filter((r) => toDate(r.t) >= since).map((r) => [toDate(r.t) / 1e3, r])));
  const xs = [...new Set(rows.flatMap((m) => [...m.keys()]))].sort((a, b) => a - b);
  box.replaceChildren();
  if (!xs.length) return box.append(el("p", { class: "muted small" }, "No readings in this period."));
  const ys = rows.map((m) => xs.map((x) => { const r = m.get(x); return r && r.qc !== 4 ? r.temp_f : null; }));
  const plugins = [nowLine()];
  if (sun) plugins.unshift(nightShade(sun));
  if (stations.length === 1) plugins.unshift(exposedShade(xs, xs.map((x) => rows[0].get(x)?.exposed)));
  const ink = cssVar("--muted"), grid = cssVar("--line");
  const ax = { stroke: ink, grid: { stroke: grid, width: 1 }, ticks: { stroke: grid }, font: "11px system-ui" };
  return new uPlot({
    width: width || box.clientWidth, height, tzDate: uplotTz, legend: { show: legend }, cursor: { y: false },
    plugins, scales: { x: { time: true } },
    axes: [{ ...ax }, { ...ax, label: "°F", size: 40, labelSize: 14 }],
    series: [{}, ...stations.map((s, i) => ({
      label: s.name, stroke: cssVar(SENSOR_SERIES[i % SENSOR_SERIES.length]), width: 1.75,
      value: (u, v) => (v == null ? "—" : `${v.toFixed(1)}°F`) }))],
  }, [xs, ...ys], box);
}

// ---------- archival HOBO record (baseline/thorndyke_hobo.json) ----------
export const cToF = (c) => (c == null ? null : c * 9 / 5 + 32);

// Daily rows as objects keyed by hobo.daily_columns.
export function hoboDays(hobo) {
  const cols = hobo?.daily_columns || [];
  return (hobo?.daily || []).map((r) => Object.fromEntries(cols.map((c, i) => [c, r[i]])));
}

// Whole record, one point per day: water mean plus the bag's daily max and min (any tide).
export function hoboChart(box, hobo, { width, height = 170, legend = true } = {}) {
  const days = hoboDays(hobo);
  box.replaceChildren();
  if (!days.length) return box.append(el("p", { class: "muted small" }, "No logger record."));
  const xs = days.map((d) => Date.parse(`${d.date}T12:00:00Z`) / 1e3);
  const ink = cssVar("--muted"), grid = cssVar("--line");
  const ax = { stroke: ink, grid: { stroke: grid, width: 1 }, ticks: { stroke: grid }, font: "11px system-ui" };
  const f1 = (u, v) => (v == null ? "—" : `${v.toFixed(1)}°F`);
  return new uPlot({
    width: width || box.clientWidth, height, tzDate: uplotTz, legend: { show: legend }, cursor: { y: false },
    scales: { x: { time: true } },
    axes: [{ ...ax }, { ...ax, label: "°F", size: 40, labelSize: 14 }],
    series: [{ value: (u, v) => (v == null ? "—" : fmt({ month: "short", day: "numeric", year: "numeric" }).format(v * 1e3)) },
      { label: "Water (daily mean)", stroke: cssVar("--series-1"), width: 2, value: f1 },
      { label: "Bag max", stroke: cssVar("--series-2"), width: 1, value: f1 },
      { label: "Bag min", stroke: cssVar("--series-3"), width: 1, value: f1 }],
  }, [xs, days.map((d) => cToF(d.water_mean)), days.map((d) => cToF(d.bag_max)), days.map((d) => cToF(d.bag_min))], box);
}

// ---------- LiveOcean model ----------
// The model is hourly. Observations are averaged onto the model hours (±30 min) so the
// chart has one x-axis and the model-vs-observation difference is a simple per-hour pair.
export function onModelHours(xs, series, key) {
  const sums = new Map();
  for (const r of series || []) {
    if (r[key] == null) continue;
    const x = Math.round(toDate(r.t) / 3600e3) * 3600;
    const s = sums.get(x) || [0, 0];
    s[0] += r[key]; s[1]++;
    sums.set(x, s);
  }
  return xs.map((x) => { const s = sums.get(x); return s ? s[0] / s[1] : null; });
}

// Mean and RMS difference (model − observed, °F) over the past `hours` where both exist.
export function modelVsObs(cell, obsSeries, hours = 7 * 24) {
  const now = Date.now() / 1e3;
  const rows = (cell?.series || []).filter((r) => { const x = toDate(r.t) / 1e3; return x <= now && x >= now - hours * 3600; });
  const xs = rows.map((r) => toDate(r.t) / 1e3);
  const obs = onModelHours(xs, obsSeries, "water_temp_f");
  const d = rows.map((r, i) => (r.temp_f != null && obs[i] != null ? r.temp_f - obs[i] : null)).filter((v) => v != null);
  if (d.length < 12) return null;
  const bias = d.reduce((a, b) => a + b, 0) / d.length;
  const rmse = Math.sqrt(d.reduce((a, b) => a + b * b, 0) / d.length);
  return { bias, rmse, n: d.length };
}

// uPlot plugin: shade the forecast part of the model run (after the run start).
function forecastShade(fromTs) {
  return {
    hooks: {
      drawClear: (u) => {
        const { ctx, bbox } = u;
        const a = Math.max(u.valToPos(fromTs, "x", true), bbox.left), b = bbox.left + bbox.width;
        if (b <= a) return;
        ctx.save();
        ctx.fillStyle = cssVar("--series-1") + "12";
        ctx.fillRect(a, bbox.top, b - a, bbox.height);
        ctx.strokeStyle = cssVar("--muted");
        ctx.setLineDash([2, 4]);
        ctx.lineWidth = devicePixelRatio;
        ctx.beginPath(); ctx.moveTo(a, bbox.top); ctx.lineTo(a, bbox.top + bbox.height); ctx.stroke();
        ctx.restore();
      },
    },
  };
}

// Model surface temperature (°F, left) and salinity (right) for one cell, with the forecast
// period shaded. `obs` overlays observed water temperature: [{ name, series: [{t, water_temp_f}] }].
export function liveoceanChart(box, lo, cellId, { width, height = 170, legend = true, sun, obs = [] } = {}) {
  const cell = lo?.cells?.find((c) => c.id === cellId);
  box.replaceChildren();
  if (!cell?.series?.length) return box.append(el("p", { class: "muted small" }, "No model data."));
  const xs = cell.series.map((r) => toDate(r.t) / 1e3);
  const overlays = obs.filter((o) => o.series?.length).map((o) => ({ ...o, ys: onModelHours(xs, o.series, "water_temp_f") }))
    .filter((o) => o.ys.some((v) => v != null));
  const ink = cssVar("--muted"), grid = cssVar("--line");
  const ax = { stroke: ink, grid: { stroke: grid, width: 1 }, ticks: { stroke: grid }, font: "11px system-ui" };
  const plugins = [forecastShade(toDate(lo.run) / 1e3), nowLine()];
  if (sun) plugins.unshift(nightShade(sun));
  const f1 = (unit) => (u, v) => (v == null ? "—" : `${v.toFixed(1)}${unit}`);
  return new uPlot({
    width: width || box.clientWidth, height, tzDate: uplotTz, legend: { show: legend }, cursor: { y: false },
    plugins,
    scales: { x: { time: true }, y2: { range: (u, mn, mx) => [Math.floor(mn - 1), Math.ceil(mx + 1)] } },
    axes: [{ ...ax }, { ...ax, label: "°F", size: 40, labelSize: 14 },
      { ...ax, side: 1, scale: "y2", label: "salinity", grid: { show: false }, size: 44, labelSize: 14 }],
    series: [{},
      { label: "Model °F", stroke: cssVar("--series-1"), width: 2, value: f1("°F") },
      { label: "Model salinity", scale: "y2", stroke: cssVar("--series-3"), width: 1.25, dash: [5, 3], value: f1("") },
      ...overlays.map((o) => ({ label: o.name, stroke: cssVar("--series-2"), width: 1, spanGaps: true, value: f1("°F") }))],
  }, [xs, cell.series.map((r) => r.temp_f), cell.series.map((r) => r.salt), ...overlays.map((o) => o.ys)], box);
}

// ---------- satellite imagery ----------
// Scenes that have a true-color product, newest first (imagery.json is already ordered that way).
export const satScenes = (imagery) => (imagery?.scenes || []).filter((s) => s.products?.truecolor?.path);
export const satLabel = (s) =>
  `${fmtDay(s.datetime)} · ${num(s.site_clear_pct, 0)}% clear · tide ${num(s.tide_ft, 1)} ft`;
